<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { detalleDistrito, listarCritica, preFacturarCiclo, preFacturarDistrito, urlExportar } from '../services/critica'
import type { Ciclo, Distrito } from '../interfaces/critica.interface'
const districts=ref<Distrito[]>([]),detail=ref<Distrito|null>(null),cycle=ref<Ciclo|null>(null),loading=ref(false),processing=ref(false),error=ref(''),success=ref('')
const money=(n:number)=>Number(n||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})
async function load(){loading.value=true;try{districts.value=(await listarCritica()).distritos}catch(e){error.value=msg(e)}finally{loading.value=false}}async function showDistrict(id:number){try{detail.value=await detalleDistrito(id)}catch(e){error.value=msg(e)}}
async function processDistrict(){if(!detail.value||!confirm(`¿Procesar nuevamente la pre-facturación de ${detail.value.nombre}?`))return;processing.value=true;try{detail.value=await preFacturarDistrito(detail.value.id);success.value='Pre-facturación distrital completada.';await load()}catch(e){error.value=msg(e)}finally{processing.value=false}}
async function processCycle(x:Ciclo){if(!confirm(`¿Generar la pre-facturación de ${x.nombre}?`))return;processing.value=true;try{cycle.value=await preFacturarCiclo(x.id);success.value='Pre-facturación del ciclo completada.';if(detail.value)detail.value=await detalleDistrito(detail.value.id);await load()}catch(e){error.value=msg(e)}finally{processing.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Facturación / Crítica</nav><header class="hero"><div class="mark">PF</div><div><small>EVAN · FACTURACIÓN</small><h1>Crítica y pre-facturación</h1><p>Revisión financiera y procesamiento de ciclos habilitados.</p></div><strong>{{districts.reduce((n,d)=>n+d.ciclos.length,0)}} ciclos habilitados</strong></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div v-if="loading" class="empty">Cargando ciclos habilitados…</div><section v-else class="districts"><article v-for="d in districts" :key="d.id" @click="showDistrict(d.id)"><div class="icon">{{d.nombre.slice(0,2).toUpperCase()}}</div><div><small>DISTRITO</small><h2>{{d.nombre}}</h2><p>{{d.ciclos.length}} ciclos en pre-facturación</p></div><span>Revisar →</span></article></section>
<div v-if="detail&&!cycle" class="backdrop" @mousedown.self="detail=null"><section class="modal wide"><header><div><small>PRE-FACTURACIÓN DISTRITAL</small><h2>{{detail.nombre}}</h2><p>{{detail.ciclos.length}} ciclos habilitados</p></div><button @click="detail=null">×</button></header><div class="toolbar"><button :disabled="processing" class="process" @click="processDistrict">{{processing?'Procesando…':'Pre-facturar distrito'}}</button><a :href="urlExportar(detail.id)">Exportar detalle</a></div><div class="cycles"><article v-for="x in detail.ciclos" :key="x.id"><header><div><b>{{x.sector}}</b><small>{{x.nombre}}</small></div><em :class="{done:x.procesado}">{{x.procesado?'Procesado':'Pendiente'}}</em></header><dl><div><dt>Total</dt><dd>S/ {{money(x.total)}}</dd></div><div><dt>Conexiones</dt><dd>{{x.conexiones}}</dd></div><div><dt>Volumen</dt><dd>{{x.volumen}} m³</dd></div></dl><footer><button @click="cycle=x">Ver resumen</button><button :disabled="processing" @click="processCycle(x)">{{x.procesado?'Reprocesar':'Procesar'}}</button></footer></article></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="cycle" class="backdrop" @mousedown.self="cycle=null"><section class="modal"><header><div><small>{{cycle.sector}}</small><h2>{{cycle.nombre}}</h2><p>Resultado de la pre-facturación</p></div><button @click="cycle=null">×</button></header><div class="kpis"><div><small>Total afecto</small><b>S/ {{money(cycle.afectos)}}</b></div><div><small>IGV</small><b>S/ {{money(cycle.igv)}}</b></div><div><small>Total inafecto</small><b>S/ {{money(cycle.inafectos)}}</b></div><div class="total"><small>Total general</small><b>S/ {{money(cycle.total)}}</b></div></div><div class="columns"><section><h3>Conceptos afectos</h3><p v-for="x in cycle.conceptos_afectos" :key="x.nombre"><span>{{x.nombre}}</span><b>{{money(x.importe)}}</b></p><h3>Conceptos inafectos</h3><p v-for="x in cycle.conceptos_inafectos" :key="x.nombre"><span>{{x.nombre}}</span><b>{{money(x.importe)}}</b></p></section><section><h3>Conexiones</h3><p><span>Volumen facturado</span><b>{{cycle.volumen}} m³</b></p><p><span>Conexiones facturadas</span><b>{{cycle.conexiones}}</b></p><p><span>Unidades de uso</span><b>{{cycle.unidades}}</b></p><h3>Categorías</h3><p v-for="x in cycle.categorias" :key="x.nombre"><span>{{x.nombre}}</span><b>{{x.cantidad}}</b></p></section></div><footer><button class="clear" @click="cycle=null">Volver</button><button :disabled="processing" @click="processCycle(cycle)">Reprocesar ciclo</button></footer></section></div></div></template>
<style scoped>
.page{--a:#7255b5;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small,.districts small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.empty{padding:50px;text-align:center;background:#fff;font-size:.6rem}.districts{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.districts>article{padding:15px;display:flex;align-items:center;gap:10px;border-top:3px solid var(--a);border-radius:9px;background:#fff;cursor:pointer}.icon{width:42px;height:42px;display:grid;place-items:center;border-radius:9px;color:#fff;background:var(--a);font-size:.55rem;font-weight:700}.districts h2{margin:2px 0;font-size:.67rem}.districts p{margin:0;color:#849096;font-size:.5rem}.districts>article>span{margin-left:auto;color:var(--a);font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.wide{width:min(100%,1000px)}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.toolbar{margin:13px 0;padding:10px;display:flex;justify-content:flex-end;gap:6px;background:#f5f7f8}.toolbar button,.toolbar a,.modal footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);text-decoration:none;font-size:.5rem}.toolbar a{background:#2c8b63}.process{background:#b34f56!important}.cycles{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.cycles article{padding:12px;border:1px solid #dfe5e7;border-radius:7px}.cycles article header{display:flex;justify-content:space-between}.cycles header b,.cycles header small{display:block;font-size:.52rem}.cycles em{font-size:.45rem;font-style:normal}.cycles em.done{color:#27805e}.cycles dl{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.cycles dt{color:#849096;font-size:.43rem}.cycles dd{margin:2px 0;font-size:.49rem;font-weight:700}.cycles footer{display:flex}.cycles footer button{flex:1;border:0;color:var(--a);background:none;font-size:.47rem}.modal>footer{margin-top:13px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.kpis{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.kpis div{padding:11px;background:#f1edfa}.kpis small,.kpis b{display:block;font-size:.52rem}.kpis .total{color:#fff;background:var(--a)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:10px}.columns section{padding:12px;border:1px solid #e1e6e8}.columns h3{font-size:.58rem}.columns p{padding:7px 0;display:flex;justify-content:space-between;border-bottom:1px solid #edf0f2;font-size:.5rem}@media(max-width:850px){.districts,.cycles{grid-template-columns:1fr 1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.districts,.cycles,.columns,.kpis{grid-template-columns:1fr}}
</style>
